// B1–B4 read-only library. Workspace/checklist state stays in the existing app.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=window.LIMI_API_BASE??'/api/legal';
const groups={tax:'Thuế',accounting:'Kế toán',labor:'Lao động',insurance:'Bảo hiểm',company:'Doanh nghiệp',commerce:'Thương mại',data:'Dữ liệu',fire:'PCCC',environment:'Môi trường',food:'An toàn thực phẩm'};
let change=()=>{},open=()=>{},requestKey='',result=null,failure='',controller;
// Dates in metadata are ISO (yyyy-mm-dd); show them the Vietnamese way.
const vnDate=v=>{const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(String(v||''));return m?`${m[3]}/${m[2]}/${m[1]}`:'';};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());
function effectLabel(m){const from=String(m?.effectiveDate||'').slice(0,10),until=String(m?.expiryDate||'').slice(0,10);if(until&&until<=today())return `Hết hiệu lực từ ${vnDate(until)}`;if(from)return from>today()?`Có hiệu lực từ ${vnDate(from)} (sắp tới)`:`Hiệu lực từ ${vnDate(from)}`;return '';}
const fileSize=b=>{const n=Number(b||0);return n>=1048576?`${(n/1048576).toFixed(1).replace('.',',')} MB`:n>=1024?`${Math.round(n/1024)} KB`:n?`${n} B`:'';};
// Stored file names are technical (hash suffixes); describe the file instead and keep the name as a hint.
function fileLabel(a){const t=String(a.mimeType||''),n=String(a.provenance?.filename||'');return /pdf/.test(t)||/\.pdf$/i.test(n)?'Bản gốc (PDF)':/html/.test(t)||/\.html?$/i.test(n)?'Trang nguồn đã lưu (HTML)':/word|officedocument|msword/.test(t)||/\.docx?$/i.test(n)?'Biểu mẫu (Word)':/sheet|excel/.test(t)||/\.xlsx?$/i.test(n)?'Biểu mẫu (Excel)':/json|gzip/.test(t)||/\.json(\.gz)?$/i.test(n)?'Dữ liệu nguồn đã thu thập (kỹ thuật)':n||a.role;}
const provisionLabel=n=>{const h=String(n.heading||'').trim();return /^Điều\s/i.test(h)?h:`Điều ${n.ordinal}${h?'. '+h:''}`;};
const params=()=>new URLSearchParams(location.search);
const link=(updates)=>{const p=params();p.set('view','laws');for(const [k,v]of Object.entries(updates)){if(v===null)p.delete(k);else p.set(k,String(v));}return `${location.pathname}?${p}`;};
const get=async(path,signal)=>{const r=await fetch(api+path,{signal,cache:'no-store'});if(!r.ok)throw Error(r.status===404?'Không tìm thấy văn bản hoặc phiên bản đã chọn.':'Chưa tải được dữ liệu luật. Bạn có thể thử lại.');return r.json();};
function navigate(url){history.pushState(null,'',url);requestKey='';result=null;failure='';open();window.scrollTo({top:0,behavior:'instant'});}
export function openLawSearch(q=''){navigate(link({law:null,snapshotId:null,parseRunId:null,provision:null,q:q||null,page:1}));}
export function configureRealLibrary(onChange,onOpen){change=onChange;open=onOpen;
  document.addEventListener('click',e=>{const a=e.target.closest('[data-real-link]');if(a){e.preventDefault();navigate(a.getAttribute('href'));}
    const search=e.target.closest('[data-find-law]');if(search){e.preventDefault();openLawSearch(search.dataset.findLaw);}
    if(e.target.closest('[data-real-retry]')){requestKey='';result=null;failure='';change();}});
  document.addEventListener('submit',e=>{if(e.target.id!=='real-law-search')return;e.preventDefault();const values=new FormData(e.target);navigate(link({law:null,snapshotId:null,parseRunId:null,provision:null,page:1,q:values.get('q')||null,scope:values.get('scope')||null,group:values.get('group')||null}));});
  window.addEventListener('popstate',()=>{requestKey='';result=null;failure='';if(params().get('view')==='laws')open();});
}
export function renderRealLibrary(){
  const p=params(),law=p.get('law');
  const heading=law?'<div data-real-library></div>':`<div class="page-title" data-real-library><div><p class="eyebrow">THƯ VIỆN PHÁP LUẬT</p><h1>Tra cứu văn bản</h1><p>Toàn văn luật, nghị định, thông tư và biểu mẫu liên quan đến doanh nghiệp. Tìm được cả khi gõ không dấu hoặc viết tắt (BHXH, TNCN, PCCC…).</p></div></div>`;
  const notice='';
  const filters=law?'':`<form id="real-law-search" class="real-filters"><label>Số hoặc tên văn bản<input name="q" value="${esc(p.get('q'))}" maxlength="200" placeholder="Ví dụ: BHXH, thuế thu nhập, 10/2020/TT-BLĐTBXH"></label><label>Phạm vi<select name="scope"><option value="">Tất cả</option><option value="NATIONAL" ${p.get('scope')==='NATIONAL'?'selected':''}>Toàn quốc</option></select></label><label>Lĩnh vực<select name="group"><option value="">Tất cả</option>${Object.entries(groups).map(([v,t])=>`<option value="${v}" ${p.get('group')===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary-button" type="submit">Tìm văn bản</button></form>`;
  if(failure)return heading+notice+filters+`<div class="empty-state" role="alert"><h2>${esc(failure)}</h2><button class="secondary-button" data-real-retry>Thử lại</button><a class="text-action" data-real-link href="${esc(link({law:null,snapshotId:null,parseRunId:null,provision:null}))}">Về danh sách</a></div>`;
  if(!result)return heading+notice+filters+`<div class="empty-state" role="status">Đang tải dữ liệu…</div>`;
  if(!law){const {list}=result;return heading+notice+filters+`<div class="section-heading real-list-summary"><p>${list.total} văn bản${list.total?` · Trang ${list.page}/${Math.max(1,Math.ceil(list.total/list.pageSize))}`:''}</p><span class="real-tag">${p.get('q')?'Phù hợp nhất trước':'Mới ban hành trước'}</span></div><div class="legal-grid">${list.items.map(d=>`<article class="legal-card"><div class="legal-card-top"><span class="legal-type">${esc(d.documentNumber)}</span><span class="real-tag">${d.scope==='HUNG_YEN'?'Địa phương':'Toàn quốc'}</span></div><h2><a data-real-link href="${esc(link({law:d.id,snapshotId:null,provision:null,parseRunId:null}))}">${esc(d.title)}</a></h2><p>${esc(d.metadata.issuingBody??'Chưa xác định cơ quan ban hành')}</p><div class="legal-card-bottom"><span>${[d.metadata.promulgationDate?'Ban hành '+vnDate(d.metadata.promulgationDate):'',effectLabel(d.metadata),groups[d.group]??d.group].filter(Boolean).map(esc).join(' · ')}</span><a class="legal-link" data-real-link href="${esc(link({law:d.id,snapshotId:null,provision:null,parseRunId:null}))}">Đọc toàn văn và nguồn →</a></div></article>`).join('')||`<div class="empty-state">${p.get('q')?`Không tìm thấy văn bản phù hợp với “${esc(p.get('q'))}”. Thư viện gồm các văn bản LIMI đã chọn lọc cho doanh nghiệp; hãy thử từ khóa khác, bỏ bộ lọc lĩnh vực hoặc tra cứu tại <a href="https://vbpl.vn" target="_blank" rel="noopener noreferrer">vbpl.vn ↗</a>.`:'Không có văn bản trong bộ lọc này. Hãy chọn lĩnh vực khác.'}</div>`}</div><nav class="real-pagination" aria-label="Chuyển trang">${list.page>1?`<a class="secondary-button" data-real-link href="${esc(link({page:list.page-1}))}">← Trang trước</a>`:''}${list.page*list.pageSize<list.total?`<a class="secondary-button" data-real-link href="${esc(link({page:list.page+1}))}">Trang sau →</a>`:''}</nav>`;}
  const {detail:d,content:c,attachments,versions,provisions,selected}=result;
  const fileUrl=a=>api+a.downloadUrl.replace('/api/v1','');
  const base={law,snapshotId:c.snapshotId,parseRunId:null,provision:null};
  const m=d.metadata||{},pdf=attachments.items.find(a=>a.status==='AVAILABLE'&&(/pdf/.test(String(a.mimeType||''))||/\.pdf$/i.test(String(a.provenance?.filename||''))));
  const facts=[['Số hiệu',d.documentNumber],['Cơ quan ban hành',m.issuingBody],['Người ký',m.signer],['Ngày ban hành',vnDate(m.promulgationDate)],['Hiệu lực',effectLabel(m)],['Lĩnh vực',groups[d.group]??m.field],['Phạm vi',d.scope==='HUNG_YEN'?'Địa phương':'Toàn quốc']].filter(([,v])=>v);
  return `<a class="text-action" data-real-link href="${esc(link({law:null,snapshotId:null,parseRunId:null,provision:null}))}">← Về danh sách văn bản</a>${heading}<section class="real-law-title"><p class="eyebrow">THƯ VIỆN PHÁP LUẬT · ${esc(d.documentNumber)}</p><h1>${esc(d.title)}</h1><dl class="real-law-facts">${facts.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>${notice}${c.quality.parseQuality?.requiresOcrTextReview?`<div class="disclaimer-banner real-ocr"><span>Toàn văn bên dưới được nhận dạng tự động từ bản scan nên có thể sai chính tả.${pdf?` Khi cần trích dẫn chính xác, hãy đối chiếu <a href="${esc(fileUrl(pdf))}">bản gốc PDF</a>.`:' Khi cần trích dẫn chính xác, hãy đối chiếu bản gốc ở nguồn bên dưới.'}</span></div>`:''}<div class="real-detail-grid"><section class="legal-card"><h2>Nguồn chính thức</h2><ul>${d.sources.map(s=>`<li><a href="${esc(s.source.url)}" target="_blank" rel="noopener noreferrer">${esc(s.source.domain)} — ${s.role==='CONTENT'?'Nội dung':'Thông tin văn bản'} ↗</a></li>`).join('')}</ul><h3>Bản lưu trên LIMI</h3><p class="field-hint">LIMI lưu một bản mới mỗi khi nguồn thay đổi.</p><div class="real-versions">${versions.items.map(s=>`<a data-real-link href="${esc(link({...base,snapshotId:s.id}))}" ${s.id===c.snapshotId?'aria-current="true"':''}>Bản lưu ngày ${esc(new Date(s.createdAt).toLocaleDateString('vi-VN'))}${s.id===c.snapshotId?' (đang xem)':''}</a>`).join('')}</div></section><section class="legal-card"><h2>Tệp gốc và biểu mẫu (${attachments.total})</h2><ul>${attachments.items.map(a=>`<li>${a.status==='AVAILABLE'?`<a href="${esc(fileUrl(a))}" title="${esc(a.provenance.filename??'')}">${esc(fileLabel(a))}</a>`:`${esc(fileLabel(a))} — chưa sẵn sàng`}${fileSize(a.sizeBytes)?` <small>· ${esc(fileSize(a.sizeBytes))}</small>`:''}</li>`).join('')||'<li>Chưa có tệp đính kèm.</li>'}</ul></section></div><section class="legal-card real-provisions"><h2>Điều luật (${provisions.total})</h2><ol>${provisions.items.map(n=>`<li><a data-real-link href="${esc(link({...base,parseRunId:provisions.parseRun.id,provision:n.id}))}">${esc(provisionLabel(n))}</a>${n.quotedAmendmentCandidate?' <small>· Trích sửa đổi</small>':''}</li>`).join('')}</ol>${provisions.total>100?'<p>Hiển thị 100 điều đầu; toàn văn bên dưới giữ đầy đủ nội dung.</p>':''}</section><section class="legal-card real-content"><h2>${selected?'Trích dẫn đã chọn':'Toàn văn'}</h2>${selected?`<a data-real-link href="${esc(link(base))}">Đọc lại toàn văn</a>`:''}<details class="real-citation"><summary>Mã trích dẫn kỹ thuật</summary><p>Phiên bản ${esc(c.snapshotId)}${selected?` · Parse ${esc(provisions.parseRun.id)} · Mục ${esc(selected.externalNodeId)}`:''}</p></details><pre>${esc(selected?.text??c.fullText)}</pre></section>`;
}
export function mountRealLibrary(){
  if(!document.querySelector('[data-real-library]'))return;
  const p=params(),key=p.toString();if(key===requestKey)return;requestKey=key;controller?.abort();controller=new AbortController();const signal=controller.signal;
  const law=p.get('law'),query=new URLSearchParams();if(p.get('snapshotId'))query.set('snapshotId',p.get('snapshotId'));
  const load=async()=>{if(!law){const q=new URLSearchParams({page:p.get('page')??'1',pageSize:'20'});for(const name of ['q','group','scope'])if(p.get(name))q.set(name,p.get(name));return {list:await get(`/laws?${q}`,signal)};}
    const base=`/laws/${encodeURIComponent(law)}`;const [detail,content,attachments,versions,provisions]=await Promise.all([get(`${base}?${query}`,signal),get(`${base}/content?${query}`,signal),get(`${base}/attachments?${query}&pageSize=100`,signal),get(`${base}/snapshots`,signal),get(`${base}/provisions?${query}&nodeType=DIEU&pageSize=100`,signal)]);
    const selected=p.get('provision')?await get(`${base}/provisions/${encodeURIComponent(p.get('provision'))}?snapshotId=${content.snapshotId}&parseRunId=${encodeURIComponent(p.get('parseRunId')??'')}`,signal):null;return {detail,content,attachments,versions,provisions,selected};};
  load().then(data=>{if(signal.aborted||requestKey!==key)return;result=data;failure='';if(document.querySelector('[data-real-library]'))change();}).catch(e=>{if(signal.aborted)return;failure=/^(Không tìm thấy|Chưa tải được)/.test(e.message)?e.message:'Chưa tải được dữ liệu luật. Kiểm tra kết nối rồi thử lại.';result=null;if(document.querySelector('[data-real-library]'))change();});
}
